head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil30301";
scwin.koList = null;
scwin.enList = null;
scwin.i = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.koList = $c.util.getComponent('koList');
        scwin.enList = $c.util.getComponent('enList');
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil30301.onpageload' });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    scwin.close();
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.init();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30301.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name rd_language_onclick
 * @description rd_language 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_language_onclick = function(e){
    try {
        scwin.checkValue('ko')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30301.rd_language_onclick' }); }
};

/**
 * @method
 * @name btn_Confirm_onclick
 * @description 「확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Confirm_onclick = async function(e){
    try {
        await scwin.confirm()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30301.btn_Confirm_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Confirm
 * @description Confirm 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Confirm = async function () {
    const sbmOptions = {
        id: "tx_fn_Confirm",
        method: "post",
        action: "/issue/certificatenolist.do",
        ref: "dma_ConfirmReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name confirm
 * @description confirm 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.confirm = async function () {
    let useCode = "";
    let useValue = "";
    for (scwin.i = 0; scwin.i < 23; scwin.i++) {
        if ((String($c.util.getComponent(["ipt_useGubun", "ipt_useGubun_2", "ipt_useGubun_3", "ipt_useGubun_4", "ipt_useGubun_5", "ipt_useGubun_6", "ipt_useGubun_7", "ipt_useGubun_8", "ipt_useGubun_9", "ipt_useGubun_10", "ipt_useGubun_11", "ipt_useGubun_12", "ipt_useGubun_13", "ipt_useGubun_14", "ipt_useGubun_15", "ipt_useGubun_16", "ipt_useGubun_17", "ipt_useGubun_18", "ipt_useGubun_19", "ipt_useGubun_20", "ipt_useGubun_21", "ipt_useGubun_22", "ipt_useGubun_23"][scwin.i]).getValue() || '') !== '') === true) {
            useCode = useCode + $c.util.getComponent(["ipt_useGubun", "ipt_useGubun_2", "ipt_useGubun_3", "ipt_useGubun_4", "ipt_useGubun_5", "ipt_useGubun_6", "ipt_useGubun_7", "ipt_useGubun_8", "ipt_useGubun_9", "ipt_useGubun_10", "ipt_useGubun_11", "ipt_useGubun_12", "ipt_useGubun_13", "ipt_useGubun_14", "ipt_useGubun_15", "ipt_useGubun_16", "ipt_useGubun_17", "ipt_useGubun_18", "ipt_useGubun_19", "ipt_useGubun_20", "ipt_useGubun_21", "ipt_useGubun_22", "ipt_useGubun_23"][scwin.i]).getValue() + ",";
            useValue = useValue + scwin.getUseValue($c.util.getComponent(["ipt_useGubun", "ipt_useGubun_2", "ipt_useGubun_3", "ipt_useGubun_4", "ipt_useGubun_5", "ipt_useGubun_6", "ipt_useGubun_7", "ipt_useGubun_8", "ipt_useGubun_9", "ipt_useGubun_10", "ipt_useGubun_11", "ipt_useGubun_12", "ipt_useGubun_13", "ipt_useGubun_14", "ipt_useGubun_15", "ipt_useGubun_16", "ipt_useGubun_17", "ipt_useGubun_18", "ipt_useGubun_19", "ipt_useGubun_20", "ipt_useGubun_21", "ipt_useGubun_22", "ipt_useGubun_23"][scwin.i]).getValue()) + ",";
        }
    }
    $c.util.getComponent('dma_ConfirmReq').set('useCode', useCode);
    $c.util.getComponent('dma_ConfirmReq').set('useValue', useValue);
    $c.util.getComponent('dma_ConfirmReq').set('listCertTpCd', "2");
    if (await scwin.elementChk()) {
        if (await $c.win.confirm("등록하시겠습니까?")) {
            (document.createForm || { elements: [] }).action = '/issue/certificatenolist.do';
            $c.util.getComponent('dma_ConfirmReq').set('method', "registerCertificateNoList");
            const nr = await scwin.tx_fn_Confirm();
            if (nr && nr.responseJSON && nr.responseJSON.success === true) {
                $c.win.moveUrl("/jldfil30300/jldfil30300.xml", { "useCode": useCode, "useValue": useValue, "listCertTpCd": "2", "method": "registerCertificateNoList" });
            }
        }
    }
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).fn_load === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).fn_load() : void 0), $c.win.closePopup([]));
    $c.win.closePopup();
};

/**
 * @method
 * @name elementChk
 * @description element Chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.elementChk = async function () {
    const form = (document.createForm || { elements: [] });
    if ($c.util.getComponent('dma_ConfirmReq').get('korengGubun')== null || $c.util.getComponent('dma_ConfirmReq').get('korengGubun')=== '') {
        await $c.win.alert("한영구분을 선택해주십시오.");
        return false;
    }
    if ($c.util.getComponent('dma_ConfirmReq').get('useCode')== null || $c.util.getComponent('dma_ConfirmReq').get('useCode')=== '') {
        await $c.win.alert("용도 구분을 1개이상 선택해주십시오.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name getUseValue
 * @description get Use Value 처리
 * @param {*} code code
 * @returns {void}
 * @hidden N
 */
scwin.getUseValue = function (code) {
    if (code === "01") {
        return "비자발급신청용";
    } else {
        if (code === "02") {
            return "법원제출용";
        } else {
            if (code === "03") {
                return "관공서제출용";
            } else {
                if (code === "04") {
                    return "은행제출용";
                } else {
                    if (code === "05") {
                        return "회사제출용";
                    } else {
                        if (code === "06") {
                            return "내부업무용";
                        } else {
                            if (code === "07") {
                                return "공증용";
                            } else {
                                if (code === "08") {
                                    return "계약체결용";
                                } else {
                                    if (code === "09") {
                                        return "확인용";
                                    } else {
                                        if (code === "10") {
                                            return "등기용";
                                        } else {
                                            if (code === "11") {
                                                return "세관제출용";
                                            } else {
                                                if (code === "12") {
                                                    return "사외이사의 대학교무처 제출용";
                                                } else {
                                                    if (code === "13") {
                                                        return "회사비치용";
                                                    } else {
                                                        if (code === "14") {
                                                            return "여권발급용";
                                                        } else {
                                                            if (code === "15") {
                                                                return "주주총회 공증용";
                                                            } else {
                                                                if (code === "16") {
                                                                    return "사업등기용";
                                                                } else {
                                                                    if (code === "17") {
                                                                        return "합병등기용";
                                                                    } else {
                                                                        if (code === "18") {
                                                                            return "국세심판소제출용";
                                                                        } else {
                                                                            if (code === "20") {
                                                                                return "Applying for Visa";
                                                                            } else {
                                                                                if (code === "21") {
                                                                                    return "New Account Opening";
                                                                                } else {
                                                                                    if (code === "22") {
                                                                                        return "EB follow up";
                                                                                    } else {
                                                                                        if (code === "23") {
                                                                                            return "Certification";
                                                                                        } else {
                                                                                            if (code === "24") {
                                                                                                return "For Submission";
                                                                                            } else {
                                                                                                return "기타";
                                                                                            }
                                                                                        }
                                                                                    }
                                                                                }
                                                                            }
                                                                        }
                                                                    }
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name checkValue
 * @description check Value 처리
 * @param {*} lang lang
 * @returns {void}
 * @hidden N
 */
scwin.checkValue = function (lang) {
    let kk = "";
    kk = $c.util.getComponent('rd_language').getValue();
    $c.util.getComponent('dma_ConfirmReq').set('korengGubun', kk);
    if (lang === "en") {
        scwin.enList.setStyle("display", "block");
        scwin.koList.setStyle("display", "none");
        $("#koList").children("input[type=checkbox][checked]").each(function() {
                $(this).attr('checked', false);
        });
    } else {
        scwin.enList.setStyle("display", "none");
        scwin.koList.setStyle("display", "block");
        $("#enList").children("input[type=checkbox][checked]").each(function() {
                $(this).attr('checked', false);
        });
    }
};
